import {mapAuthorView,mapProblemPlan,mapAuthorOrigin} from './cartographer-author.mjs';
import {mapJobs} from './cartographer-jobs.mjs';
import {marks,directions,pages} from './cartographer-content.mjs';
import {mapView,startMap,startMapJob,setMapAuthorOpen,chooseMapAuthor,startAuthoredMapJob,setMapJobView,setMapPage,selectMapMark,placeMapMark,chooseMapEndpoint,selectMapRoute,appendMapMove,removeMapMove,clearMapRoute,addMapSupport,resumeMap,mapRoutes,checkMapRoutes,mapCheckMatches} from './cartographer-core.mjs';
import {hearButton} from './play-media.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(attrs,label,selected=false)=>`<button type="button" class="${selected?'primary':'secondary'}" ${attrs}>${esc(label)}</button>`;
const name=id=>marks.find(m=>m.id===id)?.name||id;
const direction=id=>directions.find(d=>d.id===id)?.label||id;
const pair=p=>p?`(${p.x}, ${p.y})`:'unplaced';
const quantity=(n,unit)=>`${n} ${unit}${n===1?'':'s'}`;
const screen=p=>`${50+p.x*100},${550-p.y*100}`;
const help='On this practice map, start at the origin, zero across and zero up. Read the across coordinate first, then the up coordinate. North is up, east is right, south is down and west is left. Each interval between neighboring points is one model metre. Going out and back counts both intervals, even when the lines overlap.';
function key(places){return `<ul class="cart-key">${marks.map(m=>`<li><span aria-hidden="true">${esc(m.symbol)}</span><strong>${esc(m.name)}</strong><span>${pair(places?.[m.id])}</span></li>`).join('')}</ul>`;}
function grid(places,results=null,interactive=false,selected='post'){
 const point=(x,y)=>({x,y});
 const svg=`<svg class="cart-grid-art" viewBox="0 0 600 600" role="img" aria-label="Fictional grid, coordinates zero to five. Across first, then up. Route A is solid; route B is dashed. Exact positions and paths are also given in text.">${Array.from({length:6},(_,n)=>`<path d="M50 ${50+n*100}H550M${50+n*100} 50V550" fill="none" stroke="#b1c2b3" stroke-width="2"/>`).join('')}<path d="M50 50V550H550" fill="none" stroke="#183f39" stroke-width="4"/>${['a','b'].map(side=>{const points=results?.[side]?.points;if(!points?.length)return '';const end=points.at(-1),x=50+end.x*100,y=550-end.y*100;return `<polyline class="cart-path-${side}" points="${points.map(screen).join(' ')}" fill="none" stroke="${side==='a'?'#235d42':'#9a5f14'}" stroke-width="${side==='a'?7:5}"${side==='b'?' stroke-dasharray="15 9"':''} stroke-linejoin="round"/>${side==='a'?`<circle cx="${x}" cy="${y}" r="17" fill="#e7f2df" stroke="#235d42" stroke-width="4"/>`:`<rect x="${x-13}" y="${y-13}" width="26" height="26" fill="none" stroke="#9a5f14" stroke-width="4"/>`}`;}).join('')}${Array.from({length:6},(_,row)=>Array.from({length:6},(_,x)=>{const y=5-row,p=point(x,y),mark=marks.find(m=>places?.[m.id]?.x===x&&places[m.id].y===y);return `<circle cx="${50+x*100}" cy="${550-y*100}" r="${mark?(interactive?20:12):4}" fill="${mark?'#fffdf5':'#183f39'}" stroke="#183f39" stroke-width="2"/>${!interactive?`<text x="${50+x*100}" y="${575-y*100}" text-anchor="middle" font-size="18" fill="#183f39">${pair(p)}</text>${mark?`<text x="${50+x*100}" y="${556-y*100}" text-anchor="middle" font-size="22" fill="#183f39">${esc(mark.symbol)}</text>`:''}`:''}`;}).join('')).join('')}</svg>`;
 return `<figure class="cart-grid-figure"><p class="cart-axis-top">↑ North / up · y</p><div class="cart-grid${interactive?' cart-grid-interactive':''}">${svg}${interactive?`<div class="cart-point-buttons" role="group" aria-label="Place ${esc(name(selected))} at a grid intersection">${Array.from({length:6},(_,row)=>Array.from({length:6},(_,x)=>{const y=5-row,mark=marks.find(m=>places?.[m.id]?.x===x&&places[m.id].y===y),isSelected=mark?.id===selected;return `<button type="button" data-map-point="${x},${y}" aria-label="Place ${esc(name(selected))} at ${pair(point(x,y))}${mark?`; ${esc(mark.name)} is here`:''}" aria-pressed="${isSelected}"><span class="cart-point-symbol" aria-hidden="true">${mark?esc(mark.symbol):''}</span><span>${pair(point(x,y))}</span></button>`;}).join('')).join('')}</div>`:''}</div><figcaption><strong>x · across / East →</strong><span>Origin (0, 0) is at the lower left. Five intervals join six points from 0 to 5.</span>${results?'<span>Route A: solid line, circle endpoint. Route B: dashed line, square endpoint. Overlapping journeys still count every travelled interval.</span>':''}</figcaption></figure>`;
}
function endpointText(r){return `<p class="cart-trip"><strong>Start:</strong> ${esc(name(r.from))} ${pair(r.places[r.from])}<br><strong>Destination:</strong> ${esc(name(r.to))} ${pair(r.places[r.to])}</p>`;}
function resultText(result,side,recorded=false){return `<section class="cart-route-result"><h3>Route ${side}</h3><p><strong>${quantity(result.steps,'interval')} travelled · ${quantity(result.distance,'model metre')}</strong></p><p>Endpoint: ${pair(result.points.at(-1))}. ${recorded?`Recorded arrival: ${result.arrived?'yes':'no'}. Recorded blocked command: ${result.blocked??'none'}.`:result.blocked!==null?`Stopped before command ${result.blocked}: it would leave the map. That command and all later commands were not travelled. The route is not complete.`:result.commands.length===0?'No commands yet; still at the start.':result.arrived?'Completed and arrived at the destination.':'Completed, ending away from the destination.'}</p></section>`;}
function commandText(commands){return commands.length?commands.map((id,i)=>`${i+1}. ${direction(id)}`).join('; '):'No commands';}
function pointsText(points){return points.map(pair).join(' → ');}
function segmentHelp(results){return `<div class="cart-segments">${['a','b'].map(side=>`<section><h3>Route ${side.toUpperCase()} intervals in order</h3>${results[side].points.length>1?`<ol>${results[side].points.slice(1).map((p,i)=>`<li>${pair(results[side].points[i])} to ${pair(p)}: one model metre</li>`).join('')}</ol>`:'<p>No intervals travelled.</p>'}</section>`).join('')}</div>`;}
function jobRoles(r){const source=r.job.source,view=r.job.view;return `<section class="cart-job-clues"><div class="cart-job-roles" role="group" aria-label="Choose a job clue view">${[['map','Map reader'],['dispatch','Dispatcher'],['both','Both clues']].map(([id,label])=>button(`data-map-job-view="${id}" aria-pressed="${view===id}"`,`${label}${view===id?' · open':''}`,view===id)).join('')}</div><p class="tiny">Take turns with one device, or open either card whenever you like. Solo play with both clues is complete. You can speak, sign, use AAC or point; sharing is not recorded.</p>${view==='map'||view==='both'?`<section class="cart-job-card"><h3>Map reader</h3><p>${esc(source.mapReaderText)}</p>${hearButton(source.mapReaderText,'Hear the map-reader card')}<div class="cart-route-diagram">${grid(source.places)}</div>${key(source.places)}</section>`:''}${view==='dispatch'||view==='both'?`<section class="cart-job-card"><h3>Dispatcher</h3><p>${esc(source.request)}</p>${hearButton(source.request,'Hear the dispatcher’s request')}</section>`:''}</section>`;}
function jobClues(r){return r.job?`<details id="cart-job-clues" data-round="${r.id}"><summary>Clues for this job</summary>${button('data-map-job-both','Show both clues')}${jobRoles(r)}</details>`:'';}
function jobMap(r){return `<h2 id="cart-prompt" tabindex="-1">Plan a delivery together</h2><p class="cart-job-title"><strong>${esc(r.job.source.title)}</strong> · Original fiction</p>${endpointText(r)}${jobRoles(r)}<p>Where must we stop on the way? Open either clue card to plan your route.</p><p class="tiny">This job’s landmarks and endpoints stay fixed. Start a new blank map below whenever you want to move landmarks freely.</p>${button('data-map-page="route"','Make a route',true)}`;}
function recordedJobClues(source,label='Original fictional job clues kept with this check'){return `<details class="cart-job-recorded-clues"><summary>${esc(label)}</summary><h3>${esc(source.title)}</h3><p><strong>Map reader:</strong> ${esc(source.mapReaderText)}</p>${key(source.places)}<p><strong>Dispatcher:</strong> ${esc(source.request)}</p><p><strong>Required stop:</strong> ${esc(name(source.via))} ${pair(source.places[source.via])}.</p></details>`;}
function recordedJobRoute(job,side){const facts=job[side];return `<p><strong>Recorded stop visited:</strong> ${facts.visited?'yes':'no'}. <strong>Recorded request served:</strong> ${facts.fulfilled?'yes':'no'}.</p><p class="tiny">Recorded first stop position: ${facts.firstVisit===null?'none':facts.firstVisit} (route start is position 0).</p>`;}
function jobFeedback(c,jobContext){if(c.job)return `<p class="cart-job-feedback">Arrival, visiting the required stop and serving the whole request are separate recorded results. ${c.job.a.fulfilled&&c.job.b.fulfilled?'Both routes are recorded as serving this request. Thank you for planning the deliveries.':'Check the recorded stop and request results for each route. You can revise either route and check again.'}</p>`;if(jobContext)return '<p class="cart-job-feedback">This earlier check did not record the job’s required stop. Its arrival and length results stay as recorded; the whole request was not checked.</p>';return '';}
function jobCatalog(v){const n=Math.max(0,v.rounds.length-11);return `<section class="cart-job-catalog"><h3>Plan a delivery together</h3><p class="tiny">Start a supplied map with a map-reader card and dispatcher request. Starting a job creates one new sheet.${n?` It removes the oldest ${n} readable ${n===1?'map':'maps'}.`:' Earlier maps wait within the 12-readable-map limit.'}</p><div class="cart-job-choices">${mapJobs.map(job=>button(`data-map-job-start="${job.id}"`,job.title)).join('')}</div></section>`;}

function authorEntry(r){if(!r)return '<p class="tiny">Place all four landmarks to make a delivery request.</p>';const view=mapAuthorView(r);if(view.status==='unavailable')return `<aside class="cart-author-unavailable"><p>The saved delivery draft uses a format we cannot edit here. This free map and its routes remain open. A new blank map offers a fresh draft.</p><details><summary>Kept delivery draft</summary><pre>${esc(JSON.stringify(view.raw??r.authorDraft,null,2))}</pre></details></aside>`;const complete=marks.every(m=>r.places[m.id]);return `<section class="cart-author-entry">${complete?button('data-map-author-open','Make a delivery problem'):'<p>Place all four landmarks to make a delivery request.</p>'}</section>`;}
function authorPreview(plan){return plan.status==='ready'?`This request can fit our 12-move card. These conditions need at least ${plan.minimum} moves; a courier can find their own route.`:plan.status==='too-long'?`These conditions need at least ${plan.minimum} moves. Our route card holds 12 moves. Move a landmark or choose another collection point before making this request.`:plan.status==='distinct'?'Choose three different places for this request.':plan.status==='missing-map'?'Place all four landmarks to make a delivery request.':'This saved delivery draft cannot be edited here. The original map and routes remain available.';}
function authorCapacity(r,v){const n=Math.max(0,v.rounds.length-11),evictsSource=v.rounds.slice(0,n).some(x=>x.id===r.id);return `<p class="tiny cart-author-capacity">${n?`Making this request removes the oldest ${n} readable ${n===1?'map':'maps'}.`:'Making this request keeps earlier maps within the 12-readable-map limit.'}${evictsSource?' This also removes the map you are authoring from; the new job keeps its map and request, but not its older routes/checks.':''}</p>`;}
function authorMap(places){const x=n=>32+n*24,y=n=>147-n*24;return `<figure class="cart-author-map"><svg viewBox="0 0 180 180" role="img" aria-label="Our fictional map: x goes across from zero to five; y goes up from zero to five. Landmark letters and their exact coordinates are given in the key below."><rect x="1" y="1" width="178" height="178" rx="8" fill="#f6f8ef"/>${Array.from({length:6},(_,n)=>`<path d="M32 ${y(n)}H152M${x(n)} 27V147" fill="none" stroke="#b1c2b3" stroke-width="1"/><text x="${x(n)}" y="169" text-anchor="middle" font-size="16" fill="#183f39">${n}</text><text x="19" y="${y(n)+5}" text-anchor="end" font-size="16" fill="#183f39">${n}</text>`).join('')}<path d="M32 19V147H162" fill="none" stroke="#183f39" stroke-width="2"/><path d="M28 24l4-5 4 5M157 143l5 4-5 4" fill="none" stroke="#183f39" stroke-width="2"/><text x="31" y="13" text-anchor="middle" font-size="16" fill="#183f39">y</text><text x="172" y="152" text-anchor="middle" font-size="16" fill="#183f39">x</text>${marks.map(mark=>{const p=places[mark.id];return p?`<g><circle cx="${x(p.x)}" cy="${y(p.y)}" r="10" fill="#fffdf5" stroke="#397958" stroke-width="1.5"/><text x="${x(p.x)}" y="${y(p.y)+7}" text-anchor="middle" font-size="20" font-weight="bold" fill="#183f39">${esc(mark.symbol)}</text></g>`:'';}).join('')}</svg><figcaption>Across first (x), then up (y). One interval is one model metre.</figcaption></figure>`;}

function authorPage(r,v){const plan=mapProblemPlan(r),draft=plan.draft||mapAuthorView(r).draft;return `<h2 id="cart-prompt" tabindex="-1">Make a delivery problem</h2><p>Where should a courier start, collect a sealed parcel and finish?</p><div class="cart-author-layout"><section class="cart-author-picture" aria-label="Map for this request">${authorMap(r.places)}</section><section class="cart-author-selectors" aria-label="Delivery conditions">${[['from','Start at'],['via','Collect at'],['to','Deliver to']].map(([field,label])=>`<label for="cart-author-${field}">${label}<select id="cart-author-${field}" data-map-author-condition="${field}">${marks.map(m=>`<option value="${m.id}"${draft?.[field]===m.id?' selected':''}>${esc(m.name)} ${pair(r.places[m.id])}</option>`).join('')}</select></label>`).join('')}</section><section class="cart-author-key" aria-label="Landmark names and exact coordinates">${key(r.places)}</section><section class="cart-author-conditions">${plan.request?`<p class="cart-author-request"><strong>Our generated request:</strong> ${esc(plan.request)}</p>`:''}<p class="cart-author-preview">${esc(authorPreview(plan))}</p>${authorCapacity(r,v)}${button(`data-map-author-create${plan.status==='ready'?'':' disabled'}`,'Make this request on a new sheet',true)} ${button('data-map-author-close','Change our landmarks')}<p class="tiny">This chooses the conditions, not an answer route. The solving sheet starts with empty A and B routes.</p>${plan.legs?.length?`<details id="cart-author-calculation" data-round="${r.id}"><summary>How many moves do these conditions need?</summary>${plan.legs.map(leg=>`<p><strong>${esc(name(leg.from))} to ${esc(name(leg.to))}:</strong> ${leg.horizontal} across intervals + ${leg.vertical} up/down intervals = ${leg.steps} moves.</p>`).join('')}<p>At least ${plan.minimum} moves altogether. Each interval is one model metre on this unobstructed grid. Across and up/down travel are counted separately; this supplied calculation does not choose a courier’s commands.</p></details>`:''}</section></div>`;}
function authorDraftNotes(r){if(r.job||!Object.hasOwn(r,'authorDraft'))return '';const view=mapAuthorView(r);if(view.status!=='ready')return '';const draft=view.draft,plan=mapProblemPlan(r);return `<section class="cart-author-draft-notes"><h4>Current request draft — not a recorded solver outcome</h4><p><strong>Chosen start:</strong> ${esc(name(draft.from))}. <strong>Collect at:</strong> ${esc(name(draft.via))}. <strong>Deliver to:</strong> ${esc(name(draft.to))}. Authoring turn: ${draft.open?'open':'closed'}.</p>${plan.request?`<p><strong>Current generated request:</strong> ${esc(plan.request)}</p>`:''}<p><strong>Current draft status:</strong> ${esc(authorPreview(plan))}</p><p class="tiny">These are chosen conditions and a supplied planning preview. They are separate from this map’s original endpoints, routes and recorded checks; generated wording is not independently composed prose.</p></section>`;}

function authorOrigin(r,v,interactive=true){if(!r?.job)return '';const origin=mapAuthorOrigin(r.job.source);if(origin.status==='missing')return '';if(origin.status==='unavailable')return `<details class="cart-author-origin"><summary>Kept origin information</summary><p>This imported reference cannot be followed here. The job keeps its own map and request.</p><pre>${esc(JSON.stringify(origin.raw??r.job.source.authored,null,2))}</pre></details>`;const referenced=v.rounds.find(x=>x.id===origin.mapId),usable=referenced&&referenced.id!==r.id&&referenced.job===undefined;return `<aside class="cart-author-origin">${usable&&interactive?button(`data-map-author-origin="${origin.mapId}"`,`Open referenced map ${origin.mapId}`):`<p>${usable?`Referenced map ${origin.mapId} remains in the retained list.`:referenced?`Reference ${origin.mapId} does not point to a different readable free map. This job keeps its own exact map and request.`:`Referenced map ${origin.mapId} is no longer in the retained list. This job keeps its own exact map and request.`}</p>`}${referenced&&!usable?`<details><summary>Kept origin information</summary><pre>${esc(JSON.stringify(r.job.source.authored,null,2))}</pre></details>`:''}<p class="tiny">This sheet keeps its own map and request. Editing a referenced map does not change this request.</p></aside>`;}

function mapPage(r,v){if(r?.job)return jobMap(r);if(r&&mapAuthorView(r).draft?.open&&mapAuthorView(r).status==='ready')return authorPage(r,v);return `<h2 id="cart-prompt" tabindex="-1">Where shall ${esc(name(v.mark))} go?</h2><p>Choose a landmark, then tap a labelled intersection to place or move it.</p><div class="cart-mark-choices" role="group" aria-label="Choose a landmark">${marks.map(m=>button(`data-map-mark="${m.id}" aria-pressed="${v.mark===m.id}"`,`${m.symbol} ${m.name}`,v.mark===m.id)).join('')}</div>${grid(r?.places,null,true,v.mark)}${key(r?.places)}<p>Read <strong>across first, then up</strong>. Try Café at (4, 2), then Bridge at (2, 4). What changed?</p><p class="tiny">Orchard numbers name covered plots. These pairs name meeting points of grid lines. This is an invented practice map.</p>${button('data-map-page="route"','Make a route',true)}${authorEntry(r)}`;}
function endpointChoices(r){return `<div class="cart-endpoints">${[['from','Start'],['to','Destination']].map(([which,label])=>`<label>${label}<select data-map-endpoint="${which}" id="cart-${which}">${marks.map(m=>`<option value="${m.id}"${r[which]===m.id?' selected':''}${r[which==='from'?'to':'from']===m.id?' disabled':''}>${esc(m.name)} · ${pair(r.places[m.id])}</option>`).join('')}</select></label>`).join('')}</div>`;}
function routePage(r,v){const results=mapRoutes(r),side=v.side.toLowerCase(),commands=r[side];return `<h2 id="cart-prompt" tabindex="-1">Build route ${v.side}, one interval at a time</h2>${endpointText(r)}${r.job?jobClues(r):`<details id="cart-endpoint-options" data-round="${r.id}"><summary>Change start or destination</summary>${endpointChoices(r)}<p class="tiny">Changing the start, destination or map keeps both command lists. They run again from the current start.</p></details>`}${!results?'<p class="cart-notice">Place both the start and destination before travelling. <button type="button" class="text-button" data-map-page="map">Place the landmarks</button>.</p>':''}<div class="cart-side-choices" role="group" aria-label="Choose a route to edit">${['A','B'].map(s=>button(`data-map-side="${s}" aria-pressed="${v.side===s}"`,`Route ${s}${s===v.side?' · editing':''}`,s===v.side)).join('')}</div><div class="cart-moves" role="group" aria-label="Add one interval to route ${v.side}">${directions.map(d=>button(`data-map-move="${d.id}"`,d.label)).join('')}</div><p class="tiny">One move travels one model metre. Up to 12 commands per route; no diagonal moves.</p><div class="cart-route-diagram">${grid(r.places,results)}</div><section class="cart-command-list"><h3>Route ${v.side} commands (${commands.length} of 12)</h3>${commands.length?`<ol>${commands.map((id,i)=>`<li>${button(`data-map-remove="${i}" aria-label="Remove command ${i+1}: ${esc(direction(id))}"`,`${i+1}. ${direction(id)} · remove`)}${results?.[side].blocked!==null&&results?.[side].blocked<=i+1?'<span class="tiny">Not travelled</span>':''}</li>`).join('')}</ol>`:'<p>No commands yet. Choose a direction to begin.</p>'}${button('data-map-clear'+(commands.length?'':' disabled'),'Clear this route')}</section>${results?resultText(results[side],v.side):''}<aside class="cart-other-route"><h3>Route ${v.side==='A'?'B':'A'} is waiting</h3><p>${esc(commandText(r[side==='a'?'b':'a']))}</p>${results?resultText(results[side==='a'?'b':'a'],v.side==='A'?'B':'A'):''}</aside>${r.support.includes('segments')&&results?segmentHelp(results):''}${button('data-map-page="compare"','Compare both routes',true)}`;}
function jobCheckView(c,index,current,jobContext){return `<section class="cart-check" tabindex="-1"><h3>${current?'Latest check of this map':'Earlier recorded check'}${index===null?'':` ${index+1}`}</h3>${c.job?`<p><strong>Recorded request:</strong> ${esc(c.job.source.request)}</p>`:''}<div class="cart-job-check-results">${['a','b'].map(side=>{const facts=c.job?.[side];return `<section><h4>Route ${side.toUpperCase()}</h4><p><strong>Recorded arrival:</strong> ${c[side].arrived?'yes':'no'}.<br><strong>Recorded distance:</strong> ${quantity(c[side].distance,'model metre')}.<br><strong>Recorded stop visited:</strong> ${facts?facts.visited?'yes':'no':'not recorded'}.<br><strong>Recorded request served:</strong> ${facts?facts.fulfilled?'yes':'no':'not recorded'}.</p></section>`;}).join('')}</div>${jobFeedback(c,jobContext)}<details class="cart-job-check-detail"><summary>Map and routes kept with this check</summary><p class="tiny">This check keeps its own map and commands. Later edits do not change these recorded results.</p>${endpointText(c)}${c.job?recordedJobClues(c.job.source):''}${grid(c.places,{a:c.a,b:c.b})}${key(c.places)}${['a','b'].map(side=>`<div class="cart-recorded-route">${resultText(c[side],side.toUpperCase(),true)}${c.job?recordedJobRoute(c.job,side):''}<p><strong>Recorded commands:</strong> ${esc(commandText(c[side].commands))}</p><p><strong>Recorded travelled points:</strong> ${pointsText(c[side].points)}</p></div>`).join('')}<p><strong>Recorded length comparison:</strong> ${c.relation==='equal'?'A and B have equal travelled lengths.':`A is ${c.relation} than B.`}</p></details></section>`;}

function checkView(c,index,current,jobContext=false){if(c.job||jobContext)return jobCheckView(c,index,current,jobContext);return `<section class="cart-check" tabindex="-1"><h3>${current?'Latest check of this map':'Earlier recorded check'}${index===null?'':` ${index+1}`}</h3><p class="tiny">This check keeps its own map and commands. Later edits do not change these recorded results.</p>${endpointText(c)}${c.job?recordedJobClues(c.job.source):''}${grid(c.places,{a:c.a,b:c.b})}${key(c.places)}${['a','b'].map(side=>`<div class="cart-recorded-route">${resultText(c[side],side.toUpperCase(),true)}${c.job?recordedJobRoute(c.job,side):''}<p><strong>Recorded commands:</strong> ${esc(commandText(c[side].commands))}</p><p><strong>Recorded travelled points:</strong> ${pointsText(c[side].points)}</p></div>`).join('')}<p><strong>Recorded length comparison:</strong> ${c.relation==='equal'?'A and B have equal travelled lengths.':`A is ${c.relation} than B.`}</p>${jobFeedback(c,jobContext)}${c.job||jobContext?'':`<p>${c.bothArrived?c.different?'Thank you, map-maker! Both arrived. A visitor can choose between your two different routes.':'Thank you, map-maker! Both arrived. These matching routes are valid; you could try a second way.':c.a.blocked!==null||c.b.blocked!==null?'You can revise either route. A shorter travelled prefix is not a completed shortcut when commands are blocked.':'You can revise either route. Look at each recorded endpoint: which route ended away from the destination?'}</p>`}</section>`;}
function comparePage(r){const results=mapRoutes(r),latest=r.checks.at(-1);return `<h2 id="cart-prompt" tabindex="-1">Where did each route go?</h2>${endpointText(r)}${jobClues(r)}${grid(r.places,results)}${results?`<div class="cart-live-results"><div>${resultText(results.a,'A')}<p>Commands: ${esc(commandText(r.a))}</p></div><div>${resultText(results.b,'B')}<p>Commands: ${esc(commandText(r.b))}</p></div></div>`:'<p class="cart-notice">Place the start and destination to compare routes. <button type="button" class="text-button" data-map-page="map">Return to the map</button>.</p>'}<p class="tiny">Each adjacent interval is one model metre. Count travel, including out-and-back intervals, rather than dots or covered plots.</p>${r.job?'<p class="cart-job-feedback">Arrival is one part of this job. Check to record whether each route visited the required stop and served the whole request.</p>':''}${button(`data-map-check${results?'':' disabled'}`,'Check these routes',true)} ${button('data-map-page="route"','Change a route')}<p class="tiny">Up to 8 checks stay in this map. A ninth check removes the oldest.</p>${results&&r.support.includes('segments')?segmentHelp(results):''}${latest?checkView(latest,null,mapCheckMatches(r),!!r.job):'<p>No check yet. Your map and both routes stay open for changes.</p>'}${r.checks.length>1?`<details><summary>Earlier recorded checks (${r.checks.length-1})</summary>${r.checks.slice(0,-1).map((c,i)=>checkView(c,i,false,!!r.job)).join('')}</details>`:''}`;}
function history(v){return `${v.rounds.length?`<details><summary>Our maps (${v.rounds.length} of 12)</summary>${[...v.rounds].reverse().map(r=>`<p>${button(`data-map-resume="${r.id}" aria-current="${r.id===v.current?.id?'true':'false'}"`,`Map ${r.id}${r.id===v.current?.id?' (open)':''}: ${name(r.from)} to ${name(r.to)}${r.job?' · '+r.job.source.title:''}`)}</p>`).join('')}</details>`:''}${v.earlier.length?`<details><summary>Earlier unreadable work (${v.earlier.length})</summary><p>The original work is kept unchanged.</p><pre>${esc(JSON.stringify(v.earlier,null,2))}</pre></details>`:''}`;}
export function cartographerPage(state){const v=mapView(state),r=v.current,heading=`<header class="page-heading"><a class="back" href="#workshop">← Workshop</a> <a class="back" href="#post">Back to Post Office</a><h1>Cartographer’s Table</h1><p>The storm scattered our old signs. Make a map to help market visitors find their way.</p></header>`;if(v.status==='unavailable')return `<div class="cart-page">${heading}<section class="cart-sheet"><h2>Earlier work is safe</h2><p>This saved map uses a format we cannot continue here. It stays unchanged. The Workshop and Post Office remain open.</p><details><summary>See saved work</summary><pre>${esc(JSON.stringify(state.cartographer,null,2))}</pre></details></section></div>`;
 return `<div class="cart-page">${heading}<section class="cart-sheet"><nav class="cart-tabs" aria-label="Cartographer’s Table pages">${pages.map(p=>button(`data-map-page="${p}" aria-current="${v.page===p?'page':'false'}"`,p[0].toUpperCase()+p.slice(1),v.page===p)).join('')}</nav><p class="cart-status" id="cart-status" role="status" tabindex="-1"></p>${authorOrigin(r,v)}${v.page==='map'?mapPage(r,v):r?v.page==='route'?routePage(r,v):comparePage(r):`<h2 id="cart-prompt" tabindex="-1">Start a practice map</h2><p>Place two landmarks, then make and compare your own routes.</p>${button('data-map-page="map"','Place landmarks',true)}`}<details id="cart-help" data-round="${r?.id||''}"><summary>Help us read the map</summary><p>${help}</p>${hearButton(help,'Hear the map explanation')}${button('data-map-support="together"',r?.support.includes('together')?'Thinking together recorded':'We thought together')}</details>${r?button('data-map-support="segments"',r.support.includes('segments')?'Numbered intervals are shown':'Show numbered intervals'):''}<section class="cart-new"><h2>A fresh sheet</h2><p class="tiny">Up to 12 readable maps stay here.${v.rounds.length>=12?` All spaces are used. Starting a blank map removes ${quantity(v.rounds.length-11,'oldest readable map')}.`:' Starting a blank map leaves earlier maps waiting within that limit.'}</p>${button('data-map-start','Start a new blank map')}${jobCatalog(v)}</section></section><p class="cart-repeat-invitation"><a class="secondary" href="#workshop/repeats">Try a repeated delivery block</a></p>${history(v)}</div>`;
}
export function cartographerNotes(state){const v=mapView(state);if(v.status==='missing')return '';if(v.status==='unavailable')return `<details class="panel"><summary>Cartographer’s Table · earlier format</summary><pre>${esc(JSON.stringify(state.cartographer,null,2))}</pre></details>`;return `<details class="panel cart-page"><summary>Cartographer’s Table (${v.rounds.length} maps)</summary><p>Supported fictional coordinate and route practice. Equal model units and all labels are supplied. No independent map construction, physical measurement, decoding or shortest-path attainment is inferred. The latest 12 readable maps and 8 checks per map remain available; the notes download includes full original work.</p>${v.rounds.map(r=>`<section><h3>Map ${r.id}</h3>${key(r.places)}${endpointText(r)}${authorDraftNotes(r)}${authorOrigin(r,v,false)}${!r.job&&mapAuthorView(r).status==='unavailable'?`<details><summary>Kept delivery draft</summary><pre>${esc(JSON.stringify(mapAuthorView(r).raw??r.authorDraft,null,2))}</pre></details>`:''}${r.job?recordedJobClues(r.job.source,'Original fictional job clues kept with this map'):''}<p>Live route A: ${esc(commandText(r.a))}. Live route B: ${esc(commandText(r.b))}.</p><p>Support: ${esc(r.support.join(', ')||'none recorded')}.</p>${r.checks.map((c,i)=>checkView(c,i,i===r.checks.length-1&&mapCheckMatches(r),!!r.job)).join('')}</section>`).join('')}${v.earlier.length?`<pre>${esc(JSON.stringify(v.earlier,null,2))}</pre>`:''}</details>`;}
export function bindCartographer(state,{save,render,focus}){
 const boundRoundId=mapView(state).current?.id,sameMap=el=>el.isConnected&&boundRoundId!==undefined&&mapView(state).current?.id===boundRoundId;
 const show=(message='',target='#cart-prompt')=>{const roundId=mapView(state).current?.id,open=[...document.querySelectorAll('.cart-sheet details[id][data-round][open]')].filter(el=>Number(el.dataset.round)===roundId).map(el=>el.id);save();render();if(mapView(state).current?.id===roundId)for(const id of open){const el=document.getElementById(id);if(el)el.open=true;}const status=document.querySelector('#cart-status');if(status)status.textContent=message;focus(target);};
 const bind=(selector,fn)=>document.querySelectorAll(selector).forEach(b=>b.addEventListener('click',()=>fn(b)));
 bind('[data-map-author-open]',b=>{if(!sameMap(b))return;const ok=setMapAuthorOpen(state,true);show(ok?'':'The delivery draft could not be opened; the original map remains available.',ok?'#cart-prompt':'#cart-status');});
 bind('[data-map-author-close]',b=>{if(!sameMap(b))return;const ok=setMapAuthorOpen(state,false);show(ok?'Your map, routes and delivery choices are waiting.':'The draft could not be closed.',ok?'#cart-prompt':'#cart-status');});
 document.querySelectorAll('[data-map-author-condition]').forEach(select=>select.addEventListener('change',()=>{if(!sameMap(select))return;const ok=chooseMapAuthor(state,select.dataset.mapAuthorCondition,select.value);show(ok?authorPreview(mapProblemPlan(mapView(state).current)):'This delivery condition could not be changed.',`#${select.id}`);}));
 bind('[data-map-author-create]',b=>{if(!sameMap(b))return;const current=mapView(state).current,plan=mapProblemPlan(current),r=startAuthoredMapJob(state);show(r?'Our request is ready on a new sheet. Try a route, or invite another courier.':plan.status==='ready'?'A solving sheet could not be created because its saved map numbers have reached the supported limit. Your source map and draft remain unchanged.':authorPreview(plan),r?'#cart-prompt':'#cart-status');});
 bind('[data-map-author-origin]',b=>{if(!sameMap(b))return;const referenced=mapView(state).rounds.find(x=>x.id===Number(b.dataset.mapAuthorOrigin)),ok=!!referenced&&referenced.id!==boundRoundId&&referenced.job===undefined&&resumeMap(state,referenced.id);if(ok)setMapPage(state,'map');show(ok?'The referenced map is open. Editing it will not change the solving sheet’s frozen request.':'The referenced map is no longer readable. This job keeps its own map and request.',ok?'#cart-prompt':'#cart-status');});
 bind('[data-map-job-start]',b=>{const r=startMapJob(state,b.dataset.mapJobStart);show(r?'A delivery job is ready on a new sheet. Earlier maps stay in their own sheets.':'A new job sheet could not be created. Existing maps and saved work remain available.',r?'#cart-prompt':'#cart-status');});
 bind('[data-map-job-view]',b=>{const ok=setMapJobView(state,b.dataset.mapJobView);show(ok?'Clue view changed. Both route drafts stay unchanged.':'No readable delivery job is open.',`[data-map-job-view="${b.dataset.mapJobView}"]`);});
 bind('[data-map-job-both]',()=>{const ok=setMapJobView(state,'both');show(ok?'Both clues are open. Solo play is welcome.':'No readable delivery job is open.','[data-map-job-both]');});
 bind('[data-map-page]',b=>{const changed=setMapPage(state,b.dataset.mapPage);show(changed?'':'No readable map is open and a new sheet could not be created. Original saved work is kept.',changed?'#cart-prompt':'#cart-status');});
 bind('[data-map-mark]',b=>{const changed=selectMapMark(state,b.dataset.mapMark);show(changed?`Place ${name(b.dataset.mapMark)} at a labelled intersection.`:'No readable map is open and a new sheet could not be created. Original saved work is kept.',`[data-map-mark="${b.dataset.mapMark}"]`);});
 bind('[data-map-point]',b=>{const [x,y]=b.dataset.mapPoint.split(',').map(Number),result=placeMapMark(state,x,y),mark=mapView(state).mark;show(result==='fixed-job'?'This supplied job keeps its landmarks fixed. Start a new blank map for free map making.':result==='invalid'?'No readable map is open and a new map could not be created. Original saved work is kept; other destinations remain open.':result==='occupied'?'Another landmark is already at that point. Both landmarks have stayed where they were.':result==='same'?`${name(mark)} is already at (${x}, ${y}).`:`${name(mark)} is at (${x}, ${y}): ${x} across, then ${y} up.`,`[data-map-point="${x},${y}"]`);});
 document.querySelectorAll('[data-map-endpoint]').forEach(select=>select.addEventListener('change',()=>{const ok=chooseMapEndpoint(state,select.dataset.mapEndpoint,select.value);show(ok?'The route commands are kept and now run from the current start toward the current destination.':'Choose different landmarks for the start and destination.',`#${select.id}`);}));
 bind('[data-map-side]',b=>{selectMapRoute(state,b.dataset.mapSide);setMapPage(state,'route');show(`Editing route ${b.dataset.mapSide}.`,`[data-map-side="${b.dataset.mapSide}"]`);});
 const moveMessage={changed:'Move added. Earlier checks stay unchanged.',limit:'This route already has 12 commands. Remove a command before adding another.',boundary:'That move would leave the grid. No command was added.',blocked:'This route has a blocked command. Remove or clear commands before adding another.',missing:'Place both the start and destination first.',invalid:'Choose one of the four directions.'};
 bind('[data-map-move]',b=>{const result=appendMapMove(state,b.dataset.mapMove);show(moveMessage[result]||'The route is unchanged.',`[data-map-move="${b.dataset.mapMove}"]`);});
 bind('[data-map-remove]',b=>{const index=Number(b.dataset.mapRemove);removeMapMove(state,index);const v=mapView(state),length=v.current?.[v.side.toLowerCase()].length||0;show('Command removed. Earlier checks stay unchanged.',length?`[data-map-remove="${Math.min(index,length-1)}"]`:'[data-map-move]');});
 bind('[data-map-clear]',()=>{clearMapRoute(state);show('This route is empty. Earlier checks stay unchanged.','[data-map-move]');});
 bind('[data-map-check]',()=>{const check=checkMapRoutes(state);show(check?'This map and both routes have been checked. The recorded result is below.':'Place the start and destination before checking.',check?'.cart-check':'#cart-status');});
 bind('[data-map-support]',b=>{const changed=addMapSupport(state,b.dataset.mapSupport);show(!changed?'Help stays available. No support record was added because no readable map is open.':b.dataset.mapSupport==='segments'?'Numbered travelled intervals are shown below the routes.':'Thinking together recorded.',`[data-map-support="${b.dataset.mapSupport}"]`);});
 bind('[data-map-start]',()=>{const r=startMap(state);show(r?'A blank map is ready. Earlier checks stay in their own maps.':'A new map cannot be created because the saved map numbers have reached the supported limit. Existing maps remain available.',r?'#cart-prompt':'#cart-status');});
 bind('[data-map-resume]',b=>{resumeMap(state,Number(b.dataset.mapResume));show('Earlier map opened. Its recorded checks stay unchanged.');});
 const helpElement=document.querySelector('#cart-help');
 helpElement?.addEventListener('toggle',()=>{if(helpElement.open&&sameMap(helpElement)&&Number(helpElement.dataset.round)===boundRoundId){addMapSupport(state,'help');save();}});
 document.querySelectorAll('.cart-sheet [data-speak]').forEach(b=>b.addEventListener('click',()=>{if(sameMap(b)){addMapSupport(state,'audio');save();}}));
}
